    // Assuming a map to store the last timestamp for each message
    Map<String, Integer> lastTimestamps = new HashMap<>();

    // Check if the message has been printed recently
    if (lastTimestamps.containsKey(message)) {
        int lastPrintedTimestamp = lastTimestamps.get(message);
        // If the message was printed less than 10 seconds ago, return false
        if (timestamp - lastPrintedTimestamp < 10) {
            return false;
        }
    }

    // Update the last printed timestamp for the message
    lastTimestamps.put(message, timestamp);

    // Return true, indicating the message should be printed
    return true;
}

