public class TimeBucketCompressor {

    public static long compressTimeBucket(long timeBucket, int dayStep) {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("Day step must be greater than zero.");
        }

        int year = (int) (timeBucket / 10000000000L);
        int month = (int) ((timeBucket / 100000000) % 100);
        int day = (int) ((timeBucket / 1000000) % 100);

        int adjustedDay = day - (day % dayStep);
        if (adjustedDay < day) {
            adjustedDay += dayStep;
        }

        return year * 10000000000L + month * 100000000 + adjustedDay * 1000000;
    }

    public static void main(String[] args) {
        long timeBucket = 20000105;
        int dayStep = 11;
        long compressedTimeBucket = compressTimeBucket(timeBucket, dayStep);
        System.out.println("Compressed Time Bucket: " + compressedTimeBucket);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("String cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Index and length out of bounds");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xD800 || c > 0xDFFF) {
            size += 3;
        } else {
            i++; // Skip the next character as it forms a surrogate pair
            size += 4;
        }
    }
    return size;
}

