    public ByteVector(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        this.data = new byte[byteLength];
        this.length = 0;
        putByteArray(byteArrayValue, byteOffset, byteLength);
    }

    public ByteVector put(final byte value) {
        int loc0 = this.length;
        if (loc0 + 1 > data.length) {
            enlarge(1);
        }
        data[loc0++] = value;
        this.length = loc0;
        return this;
    }

    public ByteVector put(final int value) {
        int loc0 = this.length;
        if (loc0 + 4 > data.length) {
            enlarge(4);
        }
        data[loc0++] = (byte) (value >>> 24);
        data[loc0++] = (byte) (value >>> 16);
        data[loc0++] = (byte) (value >>> 8);
        data[loc0++] = (byte) value;
        this.length = loc0;
        return this;
    }

    public ByteVector put(final long value) {
        int loc0 = this.length;
        if (loc0 + 8 > data.length) {
            enlarge(8);
        }
        data[loc0++] = (byte) (value >>> 56);
        data[loc0++] = (byte) (value >>> 48);
