public class PrimeFinder {

    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity < 2) {
            return 2;
        }
        if (desiredCapacity >= 1000) {
            desiredCapacity = (int) (desiredCapacity * 1.11);
        }
        int prime = desiredCapacity;
        while (!isPrime(prime)) {
            prime++;
        }
        return prime;
    }

    private static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true;
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(nextPrime(500)); // Output: 503
        System.out.println(nextPrime(1000)); // Output: 1011
        System.out.println(nextPrime(1001)); // Output: 1011
    }
}

