public class ConstantPoolReader {

    private final byte[] classFileBuffer;

    public ConstantPoolReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) throws IOException {
        if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index");
        }

        int index = constantPoolEntryIndex * 2 + 1;
        int length = classFileBuffer[index] & 0xFF;

        if (length > charBuffer.length) {
            throw new IllegalArgumentException("Character buffer is too small");
        }

        for (int i = 0; i < length; i++) {
            charBuffer[i] = (char) (classFileBuffer[index + i + 1] & 0xFF);
        }

        return new String(charBuffer, 0, length);
    }
}

