import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class UriMatcher {

    private final Pattern pattern;
    private final List<String> variableNames;
    private final Pattern matchPattern;
    private final Map<String, String> match;

    public UriMatcher(Pattern pattern, List<String> variableNames, Pattern matchPattern, Map<String, String> match) {
        this.pattern = pattern;
        this.variableNames = variableNames;
        this.matchPattern = matchPattern;
        this.match = match;
    }

    public MatchResult match(CharSequence uri) {
        if (uri == null) {
            return null;
        }
        Matcher matcher = pattern.matcher(uri);
        if (matcher.matches()) {
            Map<String, String> result = new HashMap<>();
            for (int i = 0; i < variableNames.size(); i++) {
                result.put(variableNames.get(i), matcher.group(i + 1));
            }
            return new MatchResult(result, match);
        }
        return null;
    }

    public static class MatchResult {
        private final Map<String, String> variables;
        private final Map<String, String> match;

        public MatchResult(Map<String, String> variables, Map<String, String> match) {
            this.variables = variables;
            this.match = match;
        }

        public Map<String, String> getVariables() {
            return variables;
        }

        public Map<String, String> getMatch() {
            return match;
        }

        @Override
        public String toString() {
            return "MatchResult{" +
                    "variables=" + variables +
                    ", match=" + match +
                    '}';
        }
    }
}

