import java.util.ArrayList;
import java.util.List;

public class GraphProcessor {

    private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList(UndirectedGraph<Integer, Integer> graph) {
        List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

        for (E edge : graph.getEdges()) {
            List<Pair<Integer, Integer>> localSeparatorList = computeLocalSeparatorList(graph, edge);
            globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
        }

        return globalSeparatorList;
    }

    private List<Pair<Integer, Integer>> computeLocalSeparatorList(UndirectedGraph<Integer, Integer> graph, E edge) {
        List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
        int v = graph.getEdgeSource(edge);
        int w = graph.getEdgeTarget(edge);

        // Add all vertices in the neighborhood of v and w
        for (int u : graph.getNeighbors(v)) {
            if (u != w) {
                separatorList.add(new Pair<>(v, u));
            }
        }
        for (int u : graph.getNeighbors(w)) {
            if (u != v) {
                separatorList.add(new Pair<>(w, u));
            }
        }

        return separatorList;
    }

    public static void main(String[] args) {
        // Example usage
        UndirectedGraph<Integer, Integer> graph = new UndirectedGraph<>();
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 1);

        GraphProcessor processor = new GraphProcessor();
        List<Pair<List<Pair<Integer, Integer>>, Integer>> separators = processor.computeGlobalSeparatorList(graph);

        for (Pair<List<Pair<Integer, Integer>>, Integer> pair : separators) {
            System.out.println("Edge: " + pair.getValue1() + ", Separators: " + pair.getValue0());
        }
    }
}

