public class Graph {
    private Set<Edge> _edges;

    public Graph() {
        _edges = new HashSet<>();
    }

    public void addEdge(Edge edge) {
        _edges.add(edge);
    }

    public Edge edgeToNext() {
        if (_edges.isEmpty()) {
            return null;
        }

        Edge currentEdge = _edges.iterator().next();
        _edges.remove(currentEdge);

        return currentEdge;
    }
