public class ProtocolMessageParser {
    private int pos;
    private int count;
    private byte[] buf;

    public ProtocolMessageParser(byte[] buf) {
        this.buf = buf;
        this.pos = 0;
        this.count = buf.length;
    }

    public int readTag() throws IOException {
        if (pos < count) {
            int tag = (buf[pos++] & 0xFF) << 8;
            tag |= (buf[pos++] & 0xFF);
            return tag;
        } else {
            throw new IOException("End of input reached");
        }
    }
}

